-- 00077_interactions_citations_and_grades.sql
-- Replace retracted citation, import validated NCCIH/ODS interaction seeds, backfill null
-- interaction citations, add flagship interactions, upgrade clinical grades, sync primary_source
-- provenance, and refresh herb_page_bundles cleanly.

-- 1. Replace retracted PubMed PMID 42974326 on berberine + Metformin with verified Eur J Endocrinol 2012 RCT (PMID 22019891)
UPDATE public.drug_interactions di
SET
  evidence_level = 'moderate-evidence',
  source = 'PubMed — Eur J Endocrinol 2012: A clinical study on the short-term effect of berberine in comparison to metformin on the metabolic characteristics of women with polycystic ovary syndrome.',
  source_url = 'https://pubmed.ncbi.nlm.nih.gov/22019891/'
FROM public.herbs h
WHERE di.herb_id = h.id AND h.slug = 'berberine' AND lower(di.drug_name) = 'metformin' AND di.source_url LIKE '%42974326%';

-- 2. Apply validated NCCIH / NIH ODS seed citations (fill NULL sources & insert 29 missing clinical pairs)
UPDATE public.drug_interactions SET source = $SQLTXT$NCCIH$SQLTXT$, source_url = $SQLTXT$https://www.nccih.nih.gov/health/aloe-vera$SQLTXT$, evidence_level = coalesce(evidence_level, $SQLTXT$well-documented$SQLTXT$) WHERE id = $SQLTXT$d2e8d263-3344-4d5f-9d41-eef5e8060b91$SQLTXT$::uuid AND source IS NULL;
INSERT INTO public.drug_interactions (herb_id, drug_name, severity, description, mechanism, evidence_level, source, source_url, translations)
SELECT h.id, $SQLTXT$Hydrochlorothiazide$SQLTXT$, $SQLTXT$severe$SQLTXT$::interaction_severity, $SQLTXT$Concomitant oral ingestion of aloe latex with thiazide diuretics causes synergistic potassium wasting and acute severe hypokalemia.$SQLTXT$, $SQLTXT$Dual potassium-wasting effects across the renal distal convoluted tubule and enteric colonic mucosa.$SQLTXT$, $SQLTXT$well-documented$SQLTXT$, $SQLTXT$NCCIH$SQLTXT$, $SQLTXT$https://www.nccih.nih.gov/health/aloe-vera$SQLTXT$, $SQLTXT${"fr": {"description": "La prise orale concomitante de latex d'aloès et d'un diurétique thiazidique entraîne une perte synergique de potassium et un risque d'hypokaliémie aiguë sévère.", "mechanism": "Effets additifs de déplétion potassique au niveau du tubule contourné distal rénal et de la muqueuse colique."}}$SQLTXT$::jsonb
FROM public.herbs h WHERE h.slug = $SQLTXT$aloe-vera$SQLTXT$
AND NOT EXISTS (SELECT 1 FROM public.drug_interactions d WHERE d.herb_id = h.id AND lower(d.drug_name) = lower($SQLTXT$Hydrochlorothiazide$SQLTXT$));
