SELECT h.id, $SQLTXT$Insulin$SQLTXT$, $SQLTXT$moderate$SQLTXT$::interaction_severity, $SQLTXT$Oral aloe vera inner leaf preparations possess hypoglycemic properties that may compound insulin therapy, risking hypoglycemic episodes.$SQLTXT$, $SQLTXT$Stimulation of pancreatic insulin synthesis and secretion alongside enhanced peripheral glucose utilization.$SQLTXT$, $SQLTXT$moderate-evidence$SQLTXT$, $SQLTXT$NCCIH$SQLTXT$, $SQLTXT$https://www.nccih.nih.gov/health/aloe-vera$SQLTXT$, $SQLTXT${"fr": {"description": "Les préparations orales de gel interne d'aloe vera possèdent des propriétés hypoglycémiantes pouvant s'ajouter à l'insuline et provoquer une hypoglycémie.", "mechanism": "Potentiation de la sécrétion d'insuline pancréatique et amélioration de l'utilisation périphérique du glucose."}}$SQLTXT$::jsonb
FROM public.herbs h WHERE h.slug = $SQLTXT$aloe-vera$SQLTXT$
AND NOT EXISTS (SELECT 1 FROM public.drug_interactions d WHERE d.herb_id = h.id AND lower(d.drug_name) = lower($SQLTXT$Insulin$SQLTXT$));
