-- 4. Add verified, source-cited bilingual EN+FR interactions for high-view flagship herbs
INSERT INTO public.drug_interactions (herb_id, drug_name, severity, description, mechanism, evidence_level, source, source_url, translations)
SELECT h.id, $SQLTXT$Anticoagulants and Antiplatelets (Warfarin, Aspirin)$SQLTXT$, $SQLTXT$moderate$SQLTXT$::interaction_severity, $SQLTXT$Lion's mane extracts may inhibit platelet aggregation and slow blood clotting, potentially adding to the bleeding risk of anticoagulant or antiplatelet medications.$SQLTXT$, $SQLTXT$Inhibition of agonist-induced platelet aggregation by hericenone and erinacine fractions.$SQLTXT$, $SQLTXT$limited-evidence$SQLTXT$, $SQLTXT$LiverTox$SQLTXT$, $SQLTXT$https://www.ncbi.nlm.nih.gov/books/n/livertox/LionsMane/$SQLTXT$, $SQLTXT${"fr": {"description": "Les extraits d'hydne hérisson peuvent inhiber l'agrégation plaquettaire et ralentir la coagulation, s'ajoutant au risque hémorragique des anticoagulants ou antiagrégants.", "mechanism": "Inhibition de l'agrégation plaquettaire induite par certains agonistes sous l'effet des héricénones."}}$SQLTXT$::jsonb
FROM public.herbs h WHERE h.slug = $SQLTXT$lions-mane$SQLTXT$
AND NOT EXISTS (SELECT 1 FROM public.drug_interactions d WHERE d.herb_id = h.id AND lower(d.drug_name) = lower($SQLTXT$Anticoagulants and Antiplatelets (Warfarin, Aspirin)$SQLTXT$));
INSERT INTO public.drug_interactions (herb_id, drug_name, severity, description, mechanism, evidence_level, source, source_url, translations)
SELECT h.id, $SQLTXT$Antidiabetic medications (Metformin, Insulin)$SQLTXT$, $SQLTXT$mild$SQLTXT$::interaction_severity, $SQLTXT$Preclinical studies show Lion's mane can lower postprandial blood glucose via alpha-glucosidase inhibition, potentially producing additive hypoglycemic effects.$SQLTXT$, $SQLTXT$Inhibition of intestinal alpha-glucosidase enzymes and enhanced insulin sensitivity in preclinical models.$SQLTXT$, $SQLTXT$limited-evidence$SQLTXT$, $SQLTXT$PubMed — Planta Med 2020: Identification and alpha-Glucosidase Inhibitory Activity of Meroterpenoids from Hericium erinaceus.$SQLTXT$, $SQLTXT$https://pubmed.ncbi.nlm.nih.gov/32325508/$SQLTXT$, $SQLTXT${"fr": {"description": "Des études précliniques montrent que l'hydne hérisson peut abaisser la glycémie postprandiale via l'inhibition de l'alpha-glucosidase, avec un léger effet additif sous antidiabétiques.", "mechanism": "Inhibition de l'alpha-glucosidase intestinale et amélioration de la sensibilité à l'insuline dans les modèles expérimentaux."}}$SQLTXT$::jsonb
FROM public.herbs h WHERE h.slug = $SQLTXT$lions-mane$SQLTXT$
AND NOT EXISTS (SELECT 1 FROM public.drug_interactions d WHERE d.herb_id = h.id AND lower(d.drug_name) = lower($SQLTXT$Antidiabetic medications (Metformin, Insulin)$SQLTXT$));
INSERT INTO public.drug_interactions (herb_id, drug_name, severity, description, mechanism, evidence_level, source, source_url, translations)
SELECT h.id, $SQLTXT$Oral medications (general absorption)$SQLTXT$, $SQLTXT$moderate$SQLTXT$::interaction_severity, $SQLTXT$The thick mucilage in slippery elm coats the digestive tract and can slow or reduce the intestinal absorption of oral medications if taken simultaneously. Separate dosing by 1 to 2 hours.$SQLTXT$, $SQLTXT$Physical viscous mucilage barrier impairing tablet dissolution and mucosal drug diffusion in the gastrointestinal tract.$SQLTXT$, $SQLTXT$moderate-evidence$SQLTXT$, $SQLTXT$LiverTox$SQLTXT$, $SQLTXT$https://www.ncbi.nlm.nih.gov/books/n/livertox/SlipperyElm/$SQLTXT$, $SQLTXT${"fr": {"description": "Le mucilage visqueux de l'orme rouge tapisse la muqueuse digestive et peut ralentir ou réduire l'absorption des médicaments oraux pris simultanément. Espacer la prise de 1 à 2 heures.", "mechanism": "Barrière physique visqueuse réduisant la dissolution et la diffusion digestive des médicaments pris par voie orale."}}$SQLTXT$::jsonb
FROM public.herbs h WHERE h.slug = $SQLTXT$slippery-elm$SQLTXT$
AND NOT EXISTS (SELECT 1 FROM public.drug_interactions d WHERE d.herb_id = h.id AND lower(d.drug_name) = lower($SQLTXT$Oral medications (general absorption)$SQLTXT$));
INSERT INTO public.drug_interactions (herb_id, drug_name, severity, description, mechanism, evidence_level, source, source_url, translations)
SELECT h.id, $SQLTXT$Lithium$SQLTXT$, $SQLTXT$moderate$SQLTXT$::interaction_severity, $SQLTXT$Psyllium hydrophilic mucilloid fiber can markedly reduce gastrointestinal absorption of lithium, risking subtherapeutic mood-stabilizer serum levels unless doses are spaced apart.$SQLTXT$, $SQLTXT$Adsorption and entrapment of lithium salts within the hydrated psyllium gel matrix in the gut.$SQLTXT$, $SQLTXT$moderate-evidence$SQLTXT$, $SQLTXT$PubMed — Therapie 1990: Probable interaction of psyllium and lithium.$SQLTXT$, $SQLTXT$https://pubmed.ncbi.nlm.nih.gov/2399524/$SQLTXT$, $SQLTXT${"fr": {"description": "Les mucilages du psyllium peuvent diminuer nettement l'absorption digestive du lithium, exposant à une baisse des taux sériques thérapeutiques sans espacement des prises.", "mechanism": "Adsorption et rétention des sels de lithium dans la matrice gélifiée hydratée du psyllium."}}$SQLTXT$::jsonb
FROM public.herbs h WHERE h.slug = $SQLTXT$psyllium$SQLTXT$
AND NOT EXISTS (SELECT 1 FROM public.drug_interactions d WHERE d.herb_id = h.id AND lower(d.drug_name) = lower($SQLTXT$Lithium$SQLTXT$));
INSERT INTO public.drug_interactions (herb_id, drug_name, severity, description, mechanism, evidence_level, source, source_url, translations)
SELECT h.id, $SQLTXT$Carbamazepine$SQLTXT$, $SQLTXT$moderate$SQLTXT$::interaction_severity, $SQLTXT$Bulk-forming psyllium fiber taken concurrently can lower oral bioavailability and peak plasma concentrations of carbamazepine.$SQLTXT$, $SQLTXT$Physical binding and delayed intestinal transit reducing enteric absorption of carbamazepine.$SQLTXT$, $SQLTXT$moderate-evidence$SQLTXT$, $SQLTXT$Health Canada LNHPD$SQLTXT$, $SQLTXT$https://health-products.canada.ca/api/natural-licences/productlicence/?id=24002316&lang=en&type=json$SQLTXT$, $SQLTXT${"fr": {"description": "Les fibres mucilagineuses du psyllium prises en même temps peuvent réduire la biodisponibilité orale et les pics plasmatiques de carbamazépine.", "mechanism": "Liaison physique et modification du transit intestinal réduisant l'absorption de la carbamazépine."}}$SQLTXT$::jsonb
FROM public.herbs h WHERE h.slug = $SQLTXT$psyllium$SQLTXT$
AND NOT EXISTS (SELECT 1 FROM public.drug_interactions d WHERE d.herb_id = h.id AND lower(d.drug_name) = lower($SQLTXT$Carbamazepine$SQLTXT$));
INSERT INTO public.drug_interactions (herb_id, drug_name, severity, description, mechanism, evidence_level, source, source_url, translations)
SELECT h.id, $SQLTXT$Oral medications and Digoxin (general absorption)$SQLTXT$, $SQLTXT$moderate$SQLTXT$::interaction_severity, $SQLTXT$Bulk laxative fibers like psyllium can impair the intestinal absorption of oral drugs (including digoxin and levothyroxine) if taken at the same time; take oral medicines at least 2 hours apart.$SQLTXT$, $SQLTXT$Viscous gel formation trapping co-ingested drugs and altering gastrointestinal absorption kinetics.$SQLTXT$, $SQLTXT$well-documented$SQLTXT$, $SQLTXT$Health Canada LNHPD$SQLTXT$, $SQLTXT$https://health-products.canada.ca/api/natural-licences/productlicence/?id=24002316&lang=en&type=json$SQLTXT$, $SQLTXT${"fr": {"description": "Les laxatifs de lest comme le psyllium peuvent diminuer l'absorption digestive d'autres médicaments oraux (dont la digoxine et la lévothyroxine) pris simultanément ; espacer d'au moins 2 heures.", "mechanism": "Formation d'un gel visqueux piégeant les principes actifs co-ingérés dans le tractus digestif."}}$SQLTXT$::jsonb
FROM public.herbs h WHERE h.slug = $SQLTXT$psyllium$SQLTXT$
AND NOT EXISTS (SELECT 1 FROM public.drug_interactions d WHERE d.herb_id = h.id AND lower(d.drug_name) = lower($SQLTXT$Oral medications and Digoxin (general absorption)$SQLTXT$));
INSERT INTO public.drug_interactions (herb_id, drug_name, severity, description, mechanism, evidence_level, source, source_url, translations)
SELECT h.id, $SQLTXT$Antihypertensives and Diuretics$SQLTXT$, $SQLTXT$mild$SQLTXT$::interaction_severity, $SQLTXT$Artichoke leaf extracts possess mild choleretic and blood pressure-lowering properties that may exert modest additive hypotensive effects alongside prescription antihypertensives.$SQLTXT$, $SQLTXT$Endothelial nitric oxide synthase upregulation and mild potassium-sparing diuretic/choleretic actions.$SQLTXT$, $SQLTXT$limited-evidence$SQLTXT$, $SQLTXT$European Medicines Agency (HMPC)$SQLTXT$, $SQLTXT$https://www.ema.europa.eu/en/documents/herbal-monograph/final-european-union-herbal-monograph-cynara-cardunculus-l-syn-cynara-scolymus-l-folium_en.pdf$SQLTXT$, $SQLTXT${"fr": {"description": "L'extrait de feuille d'artichaut possède de légers effets cholérétiques et hypotenseurs pouvant s'ajouter modestement à l'action des antihypertenseurs ou diurétiques.", "mechanism": "Stimulation endothéliale de l'oxyde nitrique synthase et léger effet cholérétique et diurétique."}}$SQLTXT$::jsonb
FROM public.herbs h WHERE h.slug = $SQLTXT$artichoke$SQLTXT$
