-- 5. Upgrade clinical flagship herbs erroneously rated 'trad'
UPDATE public.herbs SET evidence_level = 'A' WHERE evidence_level = 'trad' AND slug IN ($SQLTXT$ginkgo-biloba$SQLTXT$, $SQLTXT$psyllium$SQLTXT$, $SQLTXT$horse-chestnut$SQLTXT$, $SQLTXT$kava$SQLTXT$);
UPDATE public.herbs SET evidence_level = 'B' WHERE evidence_level = 'trad' AND slug IN ($SQLTXT$milk-thistle$SQLTXT$, $SQLTXT$ginseng$SQLTXT$, $SQLTXT$hawthorn$SQLTXT$, $SQLTXT$black-cohosh$SQLTXT$, $SQLTXT$saw-palmetto$SQLTXT$, $SQLTXT$green-tea$SQLTXT$, $SQLTXT$lavender$SQLTXT$, $SQLTXT$feverfew$SQLTXT$, $SQLTXT$bacopa$SQLTXT$, $SQLTXT$elderberry$SQLTXT$, $SQLTXT$artichoke$SQLTXT$, $SQLTXT$fenugreek$SQLTXT$, $SQLTXT$red-clover$SQLTXT$, $SQLTXT$bilberry$SQLTXT$, $SQLTXT$nettle$SQLTXT$, $SQLTXT$licorice-root$SQLTXT$, $SQLTXT$maca$SQLTXT$, $SQLTXT$grape-seed$SQLTXT$, $SQLTXT$arnica$SQLTXT$, $SQLTXT$calendula$SQLTXT$, $SQLTXT$thyme$SQLTXT$, $SQLTXT$fennel$SQLTXT$, $SQLTXT$sage$SQLTXT$);
