-- 6. Sync provenance.verification_method = 'primary_source' and verified_sources on herbs backed by real monograph_sources / regulatory_evidence
WITH agg AS (
  SELECT h.id, h.provenance,
    array_agg(DISTINCT s.src_name) FILTER (WHERE s.src_name IS NOT NULL AND s.src_name <> '') AS new_sources
  FROM public.herbs h
  JOIN (
    SELECT herb_slug, source AS src_name FROM public.herb_monograph_sources
    UNION ALL
    SELECT herb_slug, source AS src_name FROM public.herb_regulatory_evidence
  ) s ON s.herb_slug = h.slug
  WHERE h.is_published = true
  GROUP BY h.id, h.provenance
), merged AS (
  SELECT a.id,
    (
      SELECT array_agg(DISTINCT v ORDER BY v)
      FROM (
        SELECT jsonb_array_elements_text(coalesce(a.provenance->'verified_sources', '[]'::jsonb)) AS v
        UNION ALL
        SELECT unnest(a.new_sources) AS v
      ) x
    ) AS combined_sources
  FROM agg a
)
UPDATE public.herbs h
SET provenance = coalesce(h.provenance, '{}'::jsonb)
  || jsonb_build_object(
       'verification_method', CASE WHEN coalesce(h.provenance->>'verification_method', '') IN ('manual') THEN h.provenance->>'verification_method' ELSE 'primary_source' END,
       'verification_status', CASE WHEN coalesce(h.provenance->>'verification_status', '') IN ('non_plant', 'formula') THEN h.provenance->>'verification_status' ELSE 'verified' END,
       'verified_sources', to_jsonb(m.combined_sources),
       'verified_source_count', coalesce(array_length(m.combined_sources, 1), 0),
       'verification_checked_at', '2026-11-16'
     )
FROM merged m
WHERE h.id = m.id
  AND coalesce(h.provenance->>'verification_method', '') NOT IN ('primary_source', 'manual');

-- 7. Replace contradictory 'states none' boilerplate on LNHPD-registered herbs cleanly (EN + FR)
UPDATE public.herbs
SET
  description = replace(description, 'Health Canada records no specific indication beyond the product''s own claim, so this entry states none.', 'Listed medicinal uses reflect those licensed product registrations rather than an independent clinical monograph.'),
  translations = CASE
    WHEN translations->'fr'->>'description' IS NOT NULL THEN jsonb_set(
      translations,
      '{fr,description}',
      to_jsonb(
        regexp_replace(
          translations->'fr'->>'description',
          '(Santé Canada ne (?:consigne|répertorie)|Santé Canada n''enregistre) aucune indication spécifique[^.]*\.',
          'Les usages inscrits proviennent uniquement de ces homologations de produits plutôt que d''une monographie clinique indépendante.'
        )
      )
    )
    ELSE translations
  END
WHERE is_published = true AND description LIKE '%Health Canada records no specific indication beyond the product''s own claim, so this entry states none.%';

UPDATE public.herbs
SET
  description = replace(description, 'The regulator records no specific indication beyond the traditional-medicine basis, so this entry claims none.', 'Listed medicinal uses reflect the traditional-medicine registration basis rather than an independent clinical monograph.'),
  translations = CASE
    WHEN translations->'fr'->>'description' IS NOT NULL THEN jsonb_set(
      translations,
      '{fr,description}',
      to_jsonb(
        regexp_replace(
          translations->'fr'->>'description',
          '(L''autorité de réglementation|Le régulateur|Santé Canada)[^.]*indication spécifique[^.]*\.',
          'Les usages médicinaux indiqués reflètent la base d''enregistrement en médecine traditionnelle plutôt qu''une monographie clinique indépendante.'
        )
      )
    )
    ELSE translations
  END
WHERE is_published = true AND description LIKE '%The regulator records no specific indication beyond%';

-- 8. Clean unpublished duplicate bundles, drain dirty bundle queue, and update planner statistics
DELETE FROM public.herb_bundle_dirty d USING public.herbs h WHERE d.slug = h.slug AND NOT h.is_published;
DELETE FROM public.herb_page_bundles b USING public.herbs h WHERE b.slug = h.slug AND NOT h.is_published;

DO $$
DECLARE refreshed integer;
BEGIN
  LOOP
    refreshed := public.refresh_herb_page_bundles(500);
    EXIT WHEN coalesce(refreshed, 0) = 0;
  END LOOP;
END $$;

ANALYZE public.herbs;
ANALYZE public.drug_interactions;
ANALYZE public.herb_faqs;
ANALYZE public.herb_page_bundles;

